// reviewTriageDir はトリアージの記録のディレクトリ。この変数が唯一の定義である。
// 別のリテラルを増やすと、移設のとき片方だけ更新されて検査が外れ、利用者はそれに気づけないため。
//
// 既定は tmp/review-triages/ (git の追跡外) で、-record-dir で上書きできる (リポジトリごとに
// ディレクトリが違うため)。表記の揺れ (".", "./rec", "rec//") は inReviewTriageDir が
// path.Dir どうしの比較で吸収するので、この値の末尾のスラッシュの有無は問わない。
var reviewTriageDir = "tmp/review-triages/"

// defaultSummaryCommand は summaryCommand のデフォルト値。定数に分けるのは、テストがデフォルト値を
// 検査するとき、run が書き換えた後の変数ではなく定数を読めるようにするためである。
const defaultSummaryCommand = "triagecheck -write-summary"

// summaryCommand はサマリの再生成手段を利用者へ案内するときに使う文字列。
// エラーの文言と、生成サマリの 1 行目に埋まる。
			"-install-wrapper で省略すると、-current-dir から見たラッパーの相対パスで組み立てる")
	if err := fs.Parse(args); err != nil {
		return err
	}

	// 明示的に渡されたフラグを集める。デフォルト値との一致では判定しない。利用者が
	// デフォルト値と同じ値を明示的に渡すことがあり、そのとき「指定していない」と誤って
	// 扱うと、不在を報告すべき経路が報告されないまま通るため。flag.Visit は実際に指定された
	// フラグだけを回すので、意思表示の有無をそのまま読める。
	explicit := map[string]bool{}
	fs.Visit(func(f *flag.Flag) { explicit[f.Name] = true })

	// 経路どうしの衝突は、パスの規則より前に見る。-install-wrapper と
	// -write-summary=true は「何を書き出すか」が矛盾するので、エラーを出さずに片方を
	// 無視すると「指定したのに適用されない」を作る。拒否するのは「何かを要求したとき」
	if _, err := os.Stat(filepath.Join(recs, "rec.md")); !os.IsNotExist(err) {
		t.Fatalf("頼んでいない生成サマリが書き出された (err=%v)", err)
	}
}

// -judgment-flow を省略したときだけ、ラッパーは $root からのデフォルトのパスを使う。
// 「デフォルトを使う」は省略で表す。明示した空は他の経路と同じく拒否される
// (TestRunRejectsEmptyExplicitPaths)。空文字を「デフォルト」の意味に使うと、
// 空のパスの規則に生成の経路だけの例外ができ、規則を足すたびに例外の処理が要る。
func TestRunInstallWrapperOmittedJudgmentFlowUsesDefault(t *testing.T) {
	withRunGlobals(t)
	t.Setenv("CLAUDE_PLUGIN_ROOT", "")
	// installWrapper は go run -C <展開先>/tools/triagecheck の位置からしか動かないので、
	// その形を満たすディレクトリを作ってそこから実行する。
	root := filepath.Join(t.TempDir(), "cache", "review-triage", "0.0.1")
	toolDir := filepath.Join(root, "tools", "triagecheck")

